import {readDemoPhoto} from './demo-photo.js?v=20261027-2';
import {scheduleDraft,scheduleFields,bindSchedule,scheduleLabel,lifecycle,publicPosts,NO_EXPIRY_NOTE} from './schedule.js?v=20261027-2';
import {createDemo,initialDraft,samples,validateDraft} from './staff-demo-model.js?v=20261027-2';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountDemo(root){
 const model=createDemo();let photoToken=0,disposed=false,simulated=false,photoBusy=false;let timing=scheduleDraft(),readSchedule,clock=Date.now();let draft=initialDraft(),editing=null,preview=false,status='';
 const $=s=>root.querySelector(s);
 function focus(s){$(s)?.focus();}
 function card(p,actions=false){const state=lifecycle(p,clock);const sample=p.photo==='local'?{src:p.image,label:'この画面で選んだ写真'}:samples[p.photo];return '<article class="demo-card '+(['ended','soldout'].includes(state)?'demo-ended':'')+'">'+(['ended','soldout'].includes(state)?'<div class="demo-ended-overlay">終了しました</div>':'')+(sample.src?'<img src="'+sample.src+'" alt="'+sample.label+(p.photo==='local'?'':'（架空の商品イラスト）')+'">':'')+'<div class="demo-card-content"><span class="demo-badge '+(['ended','soldout'].includes(state)?'ended':'')+'">'+(['ended','soldout'].includes(state)?'終了しました（デモ）':state==='scheduled'?'予約中（お客さんには非表示）':'掲載イメージ（デモ）')+'</span><h3>'+esc(p.title)+'</h3><p class="demo-body">'+esc(p.text)+'</p><p class="demo-small">'+esc(scheduleLabel(p))+'</p>'+(!p.end?'<small>'+NO_EXPIRY_NOTE+'</small>':'')+(actions?'<div class="actions"><button class="quiet" data-edit="'+p.id+'">編集する</button><button class="quiet" data-end="'+p.id+'" '+(['ended','soldout'].includes(state)?'disabled':'')+'>終了にする</button></div>':'')+'</div></article>';}
 function capture(){draft={title:$('#demo-title').value,text:$('#demo-text').value,photo:root.querySelector('input[name=sample]:checked')?.value||(draft.photo==='local'?'local':'none'),image:draft.image||'',...readSchedule()};}
 function render(target){const posts=model.list();lastLifecycle=posts.map(p=>lifecycle(p,clock)).join();root.innerHTML='<p class="demo-status" role="status" aria-live="polite" aria-atomic="true">'+esc(status)+'</p><div class="demo-grid"><section class="demo-panel" aria-labelledby="compose-heading"><p class="step-label">'+(preview?'2 / 2　見え方を確認':'1 / 2　お知らせをつくる')+'</p><h2 id="compose-heading" tabindex="-1">'+(preview?'この内容で試しますか？':editing?'デモの投稿を編集':'まずは文章と写真を選ぶ')+'</h2>'+(preview?card({...draft,state:'active'})+'<p class="demo-small">「デモ投稿する」を押すと、右側（スマホでは下）の一覧に追加されます。本番には公開されません。</p><div class="actions"><button id="demo-publish">デモ投稿する</button><button id="demo-back" class="quiet">内容に戻る</button></div>':'<form id="demo-form" novalidate><label for="demo-title">見出し（必須・40文字まで）</label><input id="demo-title" maxlength="40" required value="'+esc(draft.title)+'" aria-describedby="demo-error"><label for="demo-text">本文（必須・180文字まで）</label><textarea id="demo-text" maxlength="180" required aria-describedby="demo-counter demo-error">'+esc(draft.text)+'</textarea><p id="demo-counter" class="counter">'+draft.text.length+' / 180文字</p><fieldset><legend>写真の見本を選ぶ</legend><div class="sample-options">'+Object.entries(draft.image?{...samples,local:{label:'選んだ写真'}}:samples).map(([key,s])=>'<label class="sample-option"><input type="radio" name="sample" value="'+key+'" '+(draft.photo===key?'checked':'')+'>'+s.label+'</label>').join('')+'</div></fieldset><div id="sample-image">'+((draft.photo==='local'?draft.image:samples[draft.photo].src)?'<img class="sample-thumb" src="'+(draft.photo==='local'?draft.image:samples[draft.photo].src)+'" alt="選択中：'+(draft.photo==='local'?'この画面で選んだ写真':samples[draft.photo].label)+'">':'<p class="demo-small">写真なしでも投稿できます。</p>')+'</div><input id="demo-camera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" hidden><input id="demo-library" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="actions"><button type="button" id="demo-take-photo" class="quiet">写真を撮って試す</button><button type="button" id="demo-choose-photo" class="quiet">端末の写真を選ぶ</button></div><p class="demo-small">選んだ写真はこの画面のメモリーだけで使用し、外部に送信・端末保存しません。再読み込み・リセットで消えます。撮影画面は端末により異なります。カメラが開かない場合は写真を選ぶか見本を使ってください。JPEG・PNG・WebP、10MBまで。</p>'+scheduleFields(timing)+'<button type="submit">見え方を確認する →</button></form>')+'<p id="demo-error" role="alert"></p></section><section class="demo-panel" aria-labelledby="list-heading"><p class="step-label">予約・掲載状態の確認（店員用）</p><h2 id="list-heading" tabindex="-1">サンプル商店のお知らせ</h2><p class="demo-small">この画面だけの体験用一覧です（'+posts.length+' / 5件）。</p>'+(posts.length?posts.map(p=>card(p,true)).join(''):'<p class="demo-empty">まだデモ投稿はありません。文章と写真を選んで、見え方を試してみましょう。</p>')+'<button id="demo-new" class="quiet">新しいデモ投稿をつくる</button><div class="reset-area"><button id="demo-reset" class="quiet">デモを最初からやり直す</button><div class="reset-confirm" hidden><p>入力中の内容とデモ投稿を消して、最初に戻しますか？</p><div class="actions"><button id="reset-yes">最初に戻す</button><button id="reset-no" class="quiet">戻さない</button></div></div></div></section></div>';
 if(!preview){readSchedule=bindSchedule(root,timing);$('#demo-form').onsubmit=e=>{e.preventDefault();try{capture();draft=validateDraft(draft);preview=true;status='';render('#compose-heading');}catch(error){$('#demo-error').textContent=error.message;focus(!draft.title.trim()?'#demo-title':'#demo-text');}};$('#demo-text').oninput=()=>{$('#demo-counter').textContent=$('#demo-text').value.length+' / 180文字';};for(const r of root.querySelectorAll('input[name=sample]'))r.onchange=()=>{draft.photo=root.querySelector('input[name=sample]:checked')?.value||'none';const s=draft.photo==='local'?{src:draft.image,label:'選んだ写真'}:samples[draft.photo];$('#sample-image').innerHTML=s.src?'<img class="sample-thumb" src="'+s.src+'" alt="選択中：'+s.label+'（架空の商品イラスト）">':'<p class="demo-small">写真なしでも投稿できます。</p>';};}
 else{$('#demo-back').onclick=()=>{preview=false;render('#compose-heading');};$('#demo-publish').onclick=()=>{try{model.save(draft,editing);status=editing?'デモの投稿を更新しました。本番には公開されません。':'デモの一覧に追加しました。本番には公開されません。';draft=initialDraft();timing=scheduleDraft();editing=null;preview=false;render('#list-heading');}catch(error){$('#demo-error').textContent=error.message;}};}
 for(const b of root.querySelectorAll('[data-edit]'))b.onclick=()=>{editing=Number(b.dataset.edit);draft=model.list().find(p=>p.id===editing);timing=scheduleDraft(draft);preview=false;status='デモの投稿を編集中です。';render('#compose-heading');};
 for(const b of root.querySelectorAll('[data-end]'))b.onclick=()=>{model.end(Number(b.dataset.end));status='終了した表示に切り替えました。デモの写真と文章は残ります。';render('#list-heading');};
 $('#demo-new').onclick=()=>{photoToken++;draft=initialDraft();timing=scheduleDraft();editing=null;preview=false;status='新しいデモ投稿です。';render('#compose-heading');};
 $('#demo-reset').onclick=()=>{$('.reset-confirm').hidden=false;focus('#reset-no');};$('#reset-no').onclick=()=>{$('.reset-confirm').hidden=true;focus('#demo-reset');};$('#reset-yes').onclick=()=>{photoToken++;model.reset();draft=initialDraft();timing=scheduleDraft();editing=null;preview=false;status='デモを最初の状態に戻しました。';render('#compose-heading');};
 const panel=$('#list-heading').parentElement;const customer=root.ownerDocument.createElement('section');customer.className='demo-customer';customer.innerHTML='<h3>お客さまの表示（デモ）</h3><p class="demo-small">確認時刻：'+new Date(clock).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo'})+'（日本時間）</p><div class="actions"><button id="clock-now" class="quiet">現在時刻</button><button id="clock-start" class="quiet">直近の開始時刻を試す</button><button id="clock-end" class="quiet">直近の終了時刻を試す</button></div>'+publicPosts(posts,clock).map(p=>card(p)).join('');panel.append(customer);for(const [id,key] of [['clock-start','start'],['clock-end','end']])$('#'+id).onclick=()=>{const p=posts.find(p=>p[key]);if(p){simulated=true;clock=Date.parse(p[key]);status='デモ内の時刻だけを変更しました。';render('#list-heading');}};$('#clock-now').onclick=()=>{simulated=false;clock=Date.now();render('#list-heading');};
 if(!preview){$('#demo-take-photo').onclick=()=>$('#demo-camera').click();$('#demo-choose-photo').onclick=()=>$('#demo-library').click();const choose=async e=>{const file=e.target.files?.[0];if(!file)return;const version=++photoToken;photoBusy=true;draft.title=$('#demo-title').value;draft.text=$('#demo-text').value;for(const b of root.querySelectorAll('#demo-form button'))b.disabled=true;$('#demo-error').textContent='写真を準備しています…';try{const image=await readDemoPhoto(file);if(disposed||version!==photoToken)return;photoBusy=false;draft={...draft,photo:'local',image};render('#compose-heading');}catch(error){photoBusy=false;if(!disposed&&version===photoToken){$('#demo-error').textContent=error.message;for(const b of root.querySelectorAll('#demo-form button'))b.disabled=false;}}};$('#demo-camera').onchange=choose;$('#demo-library').onchange=choose;}
 if(target)focus(target);
 }
 let lastLifecycle='';const timer=setInterval(()=>{if(disposed||simulated||photoBusy||$('.reset-confirm')?.hidden===false)return;clock=Date.now();const next=model.list().map(p=>lifecycle(p,clock)).join();if(next===lastLifecycle)return;lastLifecycle=next;if(!preview&&$('#demo-title')){draft.title=$('#demo-title').value;draft.text=$('#demo-text').value;try{Object.assign(draft,readSchedule());}catch{}}const focused=root.ownerDocument.activeElement?.id;render(focused?'#'+focused:null);},1000);timer.unref?.();
 render();return ()=>{clearInterval(timer);disposed=true;photoToken++;model.reset();draft=initialDraft();root.replaceChildren();};
}
if(typeof document!=='undefined'){const root=document.querySelector('#demo-workspace');if(root)mountDemo(root);}
